#pragma once

/*=============================================================================
	ModuleManager.hpp: Startup and tick registration for SDK-side modules.

	A module is any class with a static Initialize() - typically one per game
	class you take over. IMPLEMENT_MODULE registers it from a file-scope object,
	so adding a module is one line at the bottom of its .cpp and nothing has to
	be edited centrally.

	Initializers run inside a structured exception handler: one module throwing
	does not stop the rest from starting, and a ticker that faults is dropped
	rather than repeating the fault every frame.

	Generated by Dumper-7. Do not edit.
=============================================================================*/

#include <chrono>
#include <cstdint>
#include <cstdio>
#include <vector>

class FModuleManager
{
public:
	using FInitializer = void (*)();
	using FTicker = void (*)(float);

	/** Receives diagnostics. Null by default, so the SDK stays silent unless asked. */
	using FLogHandler = void (*)(const char* Message);

public:
	static FModuleManager& Get()
	{
		static FModuleManager Instance;

		return Instance;
	}

	void SetLogHandler(FLogHandler Handler) { LogHandler = Handler; }

public:
	/** Runs during StartupModules, in registration order. */
	void Register(FInitializer Initializer) { Initializers.push_back(Initializer); }

	/** Runs after every Register initializer has finished, for anything that depends on them. */
	void RegisterPostLoad(FInitializer Initializer) { PostLoadInitializers.push_back(Initializer); }

	/** Runs every TickModules until it faults. */
	void RegisterTick(FTicker Ticker) { Tickers.push_back(Ticker); }

public:
	void StartupModules()
	{
		const auto StartTime = std::chrono::steady_clock::now();

		RunInitializers(Initializers);

		const double ElapsedMilliseconds = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - StartTime).count();

		if (LogHandler != nullptr)
		{
			char Message[160];
			std::snprintf(Message, sizeof(Message), "FModuleManager::StartupModules: initialized %d module(s) in %.2f ms",
				static_cast<int>(Initializers.size()), ElapsedMilliseconds);

			LogHandler(Message);
		}

		RunInitializers(PostLoadInitializers);
	}

	void TickModules(float DeltaSeconds)
	{
		for (std::size_t Index = 0; Index < Tickers.size(); )
		{
			if (RunTicker(Tickers[Index], DeltaSeconds))
			{
				Index++;
				continue;
			}

			ReportFailure("FModuleManager::TickModules: ticker raised an exception, unregistering", reinterpret_cast<void*>(Tickers[Index]));

			Tickers.erase(Tickers.begin() + Index);
		}
	}

public:
	int GetNumModules() const { return static_cast<int>(Initializers.size() + PostLoadInitializers.size()); }
	int GetNumTickers() const { return static_cast<int>(Tickers.size()); }

private:
	FModuleManager() = default;

	/*
	* The structured exception handler lives in its own leaf function: a __try block cannot sit in a
	* function that needs object unwinding, and the callers below hold containers that do.
	*/
	static bool RunGuarded(FInitializer Initializer)
	{
		__try
		{
			Initializer();
			return true;
		}
		__except (EXCEPTION_EXECUTE_HANDLER)
		{
			return false;
		}
	}

	static bool RunTicker(FTicker Ticker, float DeltaSeconds)
	{
		__try
		{
			Ticker(DeltaSeconds);
			return true;
		}
		__except (EXCEPTION_EXECUTE_HANDLER)
		{
			return false;
		}
	}

	void RunInitializers(const std::vector<FInitializer>& InInitializers)
	{
		for (const FInitializer Initializer : InInitializers)
		{
			if (!RunGuarded(Initializer))
				ReportFailure("FModuleManager::StartupModules: initializer raised an exception, skipping", reinterpret_cast<void*>(Initializer));
		}
	}

	void ReportFailure(const char* Description, void* Address) const
	{
		if (LogHandler == nullptr)
			return;

		char Message[200];
		std::snprintf(Message, sizeof(Message), "%s (at %p)", Description, Address);

		LogHandler(Message);
	}

private:
	std::vector<FInitializer> Initializers;
	std::vector<FInitializer> PostLoadInitializers;
	std::vector<FTicker> Tickers;

	FLogHandler LogHandler = nullptr;
};

/*-----------------------------------------------------------------------------
	Registration
-----------------------------------------------------------------------------*/

struct FModuleRegistrant
{
	explicit FModuleRegistrant(FModuleManager::FInitializer Initializer)
	{
		FModuleManager::Get().Register(Initializer);
	}
};

struct FPostLoadRegistrant
{
	explicit FPostLoadRegistrant(FModuleManager::FInitializer Initializer)
	{
		FModuleManager::Get().RegisterPostLoad(Initializer);
	}
};

struct FTickRegistrant
{
	explicit FTickRegistrant(FModuleManager::FTicker Ticker)
	{
		FModuleManager::Get().RegisterTick(Ticker);
	}
};

/**
 * Registers Type::Initialize to run during FModuleManager::StartupModules.
 * Put it at file scope, at the bottom of the module's .cpp.
 *
 *     IMPLEMENT_MODULE(AFortGameModeAthena);
 */
#define IMPLEMENT_MODULE(Type) \
	static FModuleRegistrant G##Type##ModuleRegistrant(&Type::Initialize)

/** Registers Type::PostLoad to run after every IMPLEMENT_MODULE initializer has finished. */
#define IMPLEMENT_MODULE_POSTLOAD(Type) \
	static FPostLoadRegistrant G##Type##PostLoadRegistrant(&Type::PostLoad)

/** Registers Type::Tick to run every FModuleManager::TickModules. */
#define IMPLEMENT_MODULE_TICK(Type) \
	static FTickRegistrant G##Type##TickRegistrant(&Type::Tick)
